// A block's outline in metres, its edges named (Phase D.2, task 3): the type and its copies' overrides read from the
// module lines of block format 4 into metres change nothing a block makes. The frozen module-line engine (legacy/) is
// the "before": the same block, generated there and, converted, generated by the live engine, must agree within 1e-6 m.
import { describe, expect, it } from 'vitest'
import { BLOCK_FORMAT, BLOCK_VERSION, BlockSchema, PROJECT_VERSION, ShapeHoleSchema, WarehouseTypeSchema, type Project, type WarehouseType } from '../../../../model/schema.ts'
import { migrate } from '../../../../model/migrate.ts'
import { blockInterior } from '../../../../io/planInterior.ts'
import { newProject } from '../../../../typologies/index.ts'
import { copyParts } from '../copies.ts'
import { copyParts as legacyCopyParts } from '../legacy/copiesLines.ts'
import { newWarehouseType } from '../defaults.ts'
import { figuresOf } from '../figures.ts'
import { generate, hallRuns, typeWith } from '../generate.ts'
import { generate as legacyGenerate, typeWith as legacyTypeWith } from '../legacy/generateLines.ts'
import { LegacyTypeSchema, type LegacyOverrides, type LegacyType } from '../legacy/types.ts'
import { migrateBlock, overridesToMetres, typeToMetres } from '../migrate.ts'
import { moduleAt } from '../bays.ts'
import { cornersOnLines, outlineOn, relaidShape, shapeOf } from '../shape.ts'

/** A block on its module lines: 72 × 48 m on 12 m bays in 4 modules (3 m): 24 × 16 modules. */
const base = (patch: Partial<LegacyType> = {}): LegacyType => ({
  ...(newWarehouseType('wt1', 'W', { program: 'warehouse' }) as unknown as LegacyType),
  hall: { length: 72, width: 48, ends: 'both' },
  elements: [],
  ...patch,
})

/** An L with a hole, a dock on its front. */
const L = (): LegacyType =>
  base({
    morphology: {
      outline: [
        { id: 'e1', x: 0, y: 0 },
        { id: 'e2', x: 24, y: 0 },
        { id: 'e3', x: 24, y: 8 },
        { id: 'e4', x: 12, y: 8 },
        { id: 'e5', x: 12, y: 16 },
        { id: 'e6', x: 0, y: 16 },
      ],
      holes: [{ id: 'h1', x: [2, 4], y: [2, 4] }],
    },
    elements: [
      { id: 'e1', kind: 'dock', edge: 'e1', module: 3, width: 3 },
      { id: 'e2', kind: 'dock', edge: 'e1', module: 4, width: 3 },
    ],
  })

/** A bump on the front, a notch on the back, two zones, the bump's face with a wall and a facade of its own. */
const bumped = (): LegacyType =>
  base({
    morphology: {
      outline: [
        { id: 'e1', x: 0, y: 2 },
        { id: 'f1', x: 8, y: 2 },
        { id: 'f2', x: 8, y: 0, thickness: 0.5, offset: 0.4 },
        { id: 'f3', x: 16, y: 0 },
        { id: 'f4', x: 16, y: 2 },
        { id: 'e2', x: 24, y: 2 },
        { id: 'e3', x: 24, y: 16 },
        { id: 'b1', x: 14, y: 16 },
        { id: 'b2', x: 14, y: 13 },
        { id: 'b3', x: 10, y: 13 },
        { id: 'b4', x: 10, y: 16 },
        { id: 'e4', x: 0, y: 16 },
      ],
      holes: [{ id: 'h1', x: [18, 21], y: [5, 9] }],
      zones: [
        { id: 'z1', x: [0, 12], y: [0, 16], program: 'office' },
        { id: 'z2', x: [12, 24], y: [0, 16] },
      ],
    },
    elements: Array.from({ length: 5 }, (_, i) => ({ id: `e${i + 1}`, kind: 'dock' as const, edge: 'f2', module: 1 + i, width: 3 })),
  })

/** Its own lines: a column line made of a module line, one taken away. */
const ownLines = (): LegacyType => ({ ...L(), grid: { ...L().grid, lines: { x: { on: [5], off: [4] }, y: { on: [3] } } } })

const FIXTURES: { name: string; type: LegacyType }[] = [
  { name: 'a plain box', type: base({ elements: [{ id: 'e1', kind: 'dock', edge: 'e1', module: 3, width: 3 }] }) },
  { name: 'an L with a hole', type: L() },
  { name: 'a bump, a notch, a hole, two zones, an edge with its own wall and offset', type: bumped() },
  { name: 'its own lines', type: ownLines() },
]

/** What `generate` makes of a type, in the shape both engines share (the live one's extra fields left out). */
function made(g: ReturnType<typeof generate>) {
  const pts = (poly: { x: number; y: number }[]) => poly.map((q) => [q.x, q.y])
  return {
    runs: { x: g.runs.x.modules, y: g.runs.y.modules, lx: g.runs.x.lines, ly: g.runs.y.lines },
    box: g.box,
    parts: g.parts.map((p) => ({ part: p.part, program: p.program, height: p.height, level: p.level, polygon: pts(p.polygon), holes: p.holes.map(pts) })),
    walls: g.walls.map((w) => ({ a: [w.a.x, w.a.y], b: [w.b.x, w.b.y], side: w.side, thickness: w.thickness, edge: w.edge ?? null, hole: w.hole ?? null })),
    columns: g.columns.map((c) => [c.x, c.y]),
    columnSize: g.columnSize,
    doors: g.doors.map((d) => ({ element: d.element, kind: d.kind, edge: d.edge, module: d.module, side: d.side, at: [d.at.x, d.at.y], width: d.width })),
    zones: g.zones.map((z) => ({ id: z.id, program: z.program, level: z.level, area: z.area, pieces: z.pieces.map(pts) })),
    edges: g.edges.map((e) => ({ id: e.id, a: [e.a.x, e.a.y], b: [e.b.x, e.b.y], side: e.side, thickness: e.thickness, offset: e.offset, outer: e.outer })),
  }
}

/** Where two values differ by more than a micrometre or are not the same (the paths). */
function differences(a: unknown, b: unknown, path = ''): string[] {
  if (typeof a === 'number' && typeof b === 'number') return Math.abs(a - b) <= 1e-6 ? [] : [`${path}: ${a} ≠ ${b}`]
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return [`${path}: ${a.length} items ≠ ${b.length}`]
    return a.flatMap((x, i) => differences(x, b[i], `${path}[${i}]`))
  }
  if (a && b && typeof a === 'object' && typeof b === 'object') {
    const keys = [...new Set([...Object.keys(a), ...Object.keys(b)])]
    return keys.flatMap((k) => differences((a as Record<string, unknown>)[k], (b as Record<string, unknown>)[k], `${path}.${k}`))
  }
  return Object.is(a, b) ? [] : [`${path}: ${String(a)} ≠ ${String(b)}`]
}

const place = { x: 120, y: 80, angle: 30 }

/** The same block, once on the frozen module-line engine, once read into metres on the live one: all that it makes. */
function agrees(t: LegacyType, o?: LegacyOverrides) {
  const before = legacyGenerate(legacyTypeWith(t, o))
  const live = typeToMetres(t)
  const own = overridesToMetres(t, o)
  const after = generate(typeWith(live, own))
  expect(differences(made(after), made(before as unknown as ReturnType<typeof generate>))).toEqual([])
  // the figures they share: the live engine's partial bays (Phase D.2, task 4) are not the frozen one's
  const figures = (g: ReturnType<typeof generate>) => {
    const { partialBays: _b, partialArea: _a, ...rest } = figuresOf({ ...g, cells: [] })
    return rest
  }
  expect(differences(figures(after), figures(before as unknown as ReturnType<typeof generate>))).toEqual([])
  // the CAD plan's interior (the frozen engine has no clipped lines: it is given the live engine's, which the walls,
  // columns and zones it compares do not depend on; the lines' own numbers are pinned in clipped.test.ts and planInterior.test.ts)
  const interior = (g: ReturnType<typeof generate>) => blockInterior(g, place)
  expect(differences(interior(after), interior({ ...(before as unknown as ReturnType<typeof generate>), lines: after.lines }))).toEqual([])
  // the mass it makes on the plan: its footprint, holes, docked walls, doors
  const mass = (parts: ReturnType<typeof copyParts>) => parts.map((p) => ({ footprint: p.footprint, holes: p.holes, docks: p.docks, doorsAt: p.doorsAt, blockCourts: p.blockCourts, height: p.height, zones: p.zones }))
  expect(differences(mass(copyParts(live, { place, overrides: own })), mass(legacyCopyParts(t, { place, overrides: o }) as unknown as ReturnType<typeof copyParts>))).toEqual([])
}

describe('a block in metres makes what it made on its module lines', () => {
  for (const { name, type } of FIXTURES)
    it(`${name}`, () => {
      expect(LegacyTypeSchema.safeParse(type).success).toBe(true)
      agrees(type)
      expect(WarehouseTypeSchema.safeParse(typeToMetres(type)).success).toBe(true)
    })

  it('a variant of another size: longer, shorter, wider (its type’s outline anchored to its box)', () => {
    for (const hall of [{ length: 84 }, { length: 96 }, { length: 60 }, { width: 60 }, { length: 84, width: 60 }])
      for (const { type } of FIXTURES) agrees(type, { hall })
  })

  it('a variant with an outline of its own, on a box of its own', () => {
    const t = L()
    const o: LegacyOverrides = {
      hall: { length: 84 },
      morphology: {
        outline: [
          { id: 'e1', x: 0, y: 0 },
          { id: 'e2', x: 28, y: 0 },
          { id: 'e3', x: 28, y: 6 },
          { id: 'e4', x: 14, y: 6 },
          { id: 'e5', x: 14, y: 16 },
          { id: 'e6', x: 0, y: 16 },
        ],
        holes: [{ id: 'h1', x: [2, 4], y: [2, 4] }],
      },
      elements: [{ id: 'e1', kind: 'dock', edge: 'e1', module: 5, width: 3 }],
    }
    agrees(t, o)
  })

  it('a copy that changes only its zones or a figure of its own', () => {
    agrees(bumped(), { envelope: { height: 9 }, columns: { size: 0.6 } })
    agrees(bumped(), { morphology: { zones: [{ id: 'z1', x: [0, 24], y: [0, 16], program: 'office' }] } })
  })
})

describe('the type in metres', () => {
  it('its corners are the module lines in metres (moduleAt of its runs), ids kept; its holes contours', () => {
    const t = L()
    const r = typeToMetres(t)
    const runs = hallRuns(r)
    expect(r.morphology.outline.map((c) => c.id)).toEqual(['e1', 'e2', 'e3', 'e4', 'e5', 'e6'])
    expect(r.morphology.outline[2]).toMatchObject({ id: 'e3', x: moduleAt(runs.x, 24), y: moduleAt(runs.y, 8) })
    expect(r.morphology.outline[3]).toMatchObject({ x: moduleAt(runs.x, 12), y: moduleAt(runs.y, 8) })
    const h = r.morphology.holes[0]
    expect(h.id).toBe('h1')
    expect(h.vertices.map((v) => [v.x, v.y])).toEqual([
      [moduleAt(runs.x, 2), moduleAt(runs.y, 2)],
      [moduleAt(runs.x, 4), moduleAt(runs.y, 2)],
      [moduleAt(runs.x, 4), moduleAt(runs.y, 4)],
      [moduleAt(runs.x, 2), moduleAt(runs.y, 4)],
    ])
    expect(h.vertices.every((v) => v.r === 0)).toBe(true)
    // a box: no outline of its own
    expect(typeToMetres(base()).morphology.outline).toEqual([])
    // its elements, zones and walls as they were
    const b = typeToMetres(bumped())
    expect(b.morphology.zones).toEqual(bumped().morphology.zones)
    expect(b.morphology.outline.find((c) => c.id === 'f2')).toMatchObject({ thickness: 0.5, offset: 0.4 })
    expect(b.elements).toEqual(bumped().elements)
  })

  it('a hole in module lines is no hole now (the block’s schema reads a contour)', () => {
    expect(ShapeHoleSchema.safeParse({ id: 'h1', x: [2, 4], y: [2, 4] }).success).toBe(false)
    expect(ShapeHoleSchema.safeParse({ id: 'h1', vertices: [{ x: 0, y: 0, r: 0 }, { x: 4, y: 0, r: 0 }, { x: 4, y: 4, r: 0 }], corridor: 2 }).success).toBe(true)
  })

  it('an outline corner takes a chamfer, a radius, an arc: they round-trip through the schema and JSON', () => {
    const t = typeToMetres(L())
    const rounded: WarehouseType = {
      ...t,
      morphology: {
        ...t.morphology,
        outline: t.morphology.outline.map((c, i) => (i === 1 ? { ...c, chamfer: [1, 2] as [number, number] } : i === 2 ? { ...c, r: 1.5 } : c)),
        arcs: { '0': -0.2 },
      },
    }
    const back = WarehouseTypeSchema.parse(JSON.parse(JSON.stringify(rounded)))
    expect(back.morphology.outline[1].chamfer).toEqual([1, 2])
    expect(back.morphology.outline[2].r).toBe(1.5)
    expect(back.morphology.arcs).toEqual({ '0': -0.2 })
  })

  it('the versions: project 18, block 6 (Phase D.3: a truck court’s own shape)', () => {
    expect(PROJECT_VERSION).toBe(20)
    expect(BLOCK_VERSION).toBe(6)
  })
})

describe('older files read into metres', () => {
  const inProject = (types: LegacyType[], buildings: unknown[] = [], masses: unknown[] = []) => {
    const p = newProject('industrial') as unknown as Record<string, unknown>
    return { ...p, version: 16, warehouseTypes: types, buildings: [...(p.buildings as unknown[]), ...buildings], masses: [...(p.masses as unknown[]), ...masses] }
  }

  it('a project of version 16: its types in metres, its free mass a block of its program (Phase D.2 task 8), version 18', () => {
    const t = bumped()
    const mass = { id: 'm1', name: 'Hall', levelId: 'l1', programId: 'warehouse', footprint: { kind: 'rect', center: { x: 0, y: 0 }, width: 10, depth: 10, rotation: 0 }, height: 12 }
    const v16 = inProject([t], [], [mass])
    const r = migrate(v16) as unknown as Project
    expect(r.version).toBe(20)
    expect(r.warehouseTypes![0]).toEqual(typeToMetres(t))
    expect(r.masses.find((m) => m.id === 'm1')).toMatchObject({ id: 'm1', name: 'Hall', programId: 'warehouse', part: 'hall', height: 12 })
    const o = r.warehouseTypes![0].morphology.outline.find((c) => c.id === 'f4')!
    const runs = hallRuns(r.warehouseTypes![0])
    expect([o.x, o.y]).toEqual([moduleAt(runs.x, 16), moduleAt(runs.y, 2)])
    // stopping at 16 keeps the module lines
    const at16 = migrate(inProject([t]), 16) as unknown as Record<string, unknown>
    expect((at16.warehouseTypes as LegacyType[])[0].morphology.outline[4]).toMatchObject({ id: 'f4', x: 16, y: 2 })
  })

  it('a copy’s overrides read into metres too (its own outline on its box now)', () => {
    const t = L()
    const o: LegacyOverrides = { hall: { length: 84 }, morphology: { outline: [{ id: 'e1', x: 0, y: 0 }, { id: 'e2', x: 28, y: 0 }, { id: 'e3', x: 28, y: 16 }, { id: 'e4', x: 0, y: 16 }], holes: [] } }
    const building = { id: 'b9', name: 'Copy', color: '#ccc', levelHeight: 12, levels: [{ id: 'l9', name: 'L1', elevation: 0, height: 12, repeat: 1 }], warehouse: { type: t.id, place: { x: 0, y: 0, angle: 0 }, overrides: o } }
    const r = migrate(inProject([t], [building])) as unknown as Project
    const copy = r.buildings.find((b) => b.id === 'b9')!.warehouse!
    const live = r.warehouseTypes![0]
    expect(differences(made(generate(typeWith(live, copy.overrides))), made(legacyGenerate(legacyTypeWith(t, o)) as unknown as ReturnType<typeof generate>))).toEqual([])
    expect(copy.overrides!.morphology!.outline![1]).toMatchObject({ id: 'e2', x: 84 })
  })

  it('a block file of format 4 reads as format 6; so does one of format 3', () => {
    const t = bumped()
    const file = { format: BLOCK_FORMAT, formatVersion: 4, id: 'b1', version: 1, savedAt: 0, type: t, programs: [{ id: 'warehouse', name: 'Warehouse', color: '#999', built: true, kind: 'warehouse' }, { id: 'office', name: 'Office', color: '#aaa', built: true }] }
    const r = BlockSchema.safeParse(migrateBlock(file))
    expect(r.success).toBe(true)
    expect(r.data!.formatVersion).toBe(6)
    expect(r.data!.type).toEqual(typeToMetres(t))
    const old = { ...file, formatVersion: 3 }
    const r3 = BlockSchema.safeParse(migrateBlock(old))
    expect(r3.success).toBe(true)
    expect(r3.data!.formatVersion).toBe(6)
    expect(differences(made(generate(r3.data!.type)), made(legacyGenerate(t) as unknown as ReturnType<typeof generate>))).toEqual([])
  })
})

describe('a copy whose runs differ from its type’s at the same box size (review fix)', () => {
  const overrides: [string, unknown][] = [
    ['ends start', { hall: { ends: 'start' } }],
    ['ends none', { hall: { ends: 'none' } }],
    ['grid x 10', { grid: { x: 10 } }],
    ['grid x 9, 3 modules', { grid: { x: 9, modules: 3 } }],
    ['own lines', { grid: { lines: { x: { on: [5], off: [4] }, y: { on: [3] } } } }],
  ]
  for (const [name, o] of overrides)
    for (const [which, type] of [['an L with a hole', L()], ['a bump and a notch', bumped()]] as const)
      it(`${name} on ${which}: the notch and the hole stay where the copy showed them`, () => agrees(type, o as LegacyOverrides))

  it('a hole of its own only, on the type’s outline: where it was drawn', () => {
    for (const o of [
      { morphology: { holes: [{ id: 'h2', x: [6, 8], y: [6, 8] }] } },
      { hall: { ends: 'start' }, morphology: { holes: [{ id: 'h2', x: [6, 8], y: [6, 8] }] } },
      { grid: { x: 10 }, morphology: { holes: [{ id: 'h2', x: [6, 8], y: [6, 8] }] } },
    ] as unknown as LegacyOverrides[])
      for (const type of [L(), base()]) agrees(type, o)
  })

  it('an empty outline with holes of its own: the box, those holes', () => {
    const o = { morphology: { outline: [], holes: [{ id: 'h2', x: [6, 8], y: [6, 8] }] } } as unknown as LegacyOverrides
    for (const type of [L(), base(), bumped()]) agrees(type, o)
  })
})

describe('the outline on a box of another size', () => {
  const live = () => typeToMetres(L())

  it('each corner keeps its distance in metres from the nearer wall of the box it was drawn on', () => {
    const t = live()
    const longer = typeWith(t, { hall: { length: 96 } })
    const o = shapeOf(longer, hallRuns(longer)).outline
    // the L's low corners stay, the far wall’s go 24 m on (72 → 96)
    expect(o.map((c) => [c.x, c.y])).toEqual([[0, 0], [96, 0], [96, 24], [36, 24], [36, 48], [0, 48]])
    const wider = typeWith(t, { hall: { width: 60 } })
    expect(shapeOf(wider, hallRuns(wider)).outline.map((c) => [c.x, c.y])).toEqual([[0, 0], [72, 0], [72, 24], [36, 24], [36, 60], [0, 60]])
  })

  it('a box relaid at its size keeps the outline in metres; its zones go to the nearest lines', () => {
    const t = typeToMetres(bumped())
    const before = hallRuns(t)
    const after = hallRuns({ ...t, hall: { ...t.hall, ends: 'start' } })
    const laid = relaidShape({ ...t.morphology }, before, after)
    expect(laid).not.toBeNull()
    expect(laid!.outline).toEqual(t.morphology.outline)
    expect(laid!.holes).toEqual(t.morphology.holes)
    // the zones are still rectangles of module lines, each side on the line nearest where it stood
    const wall = moduleAt(before.x, 12)
    const k = laid!.zones![0].x[1]
    expect(Math.abs(moduleAt(after.x, k) - wall)).toBeLessThanOrEqual(Math.abs(moduleAt(after.x, k - 1) - wall))
    expect(Math.abs(moduleAt(after.x, k) - wall)).toBeLessThanOrEqual(Math.abs(moduleAt(after.x, k + 1) - wall))
  })

  it('outlineOn reads the type as the box now (a box with no outline: its four corners)', () => {
    const t = typeToMetres(base())
    expect(outlineOn(t, hallRuns(t)).map((c) => [c.id, c.x, c.y])).toEqual([['e1', 0, 0], ['e2', 72, 0], ['e3', 72, 48], ['e4', 0, 48]])
  })
})

describe('cornersOnLines', () => {
  it('reads a box with a bump back as module lines', () => {
    const t = typeToMetres(bumped())
    const lines = cornersOnLines(t)
    expect(lines).toEqual(bumped().morphology.outline)
  })

  it('an outline off the module lines is null; a box is its four corners', () => {
    const t = typeToMetres(L())
    const off: WarehouseType = { ...t, morphology: { ...t.morphology, outline: t.morphology.outline.map((c, i) => (i === 3 ? { ...c, x: c.x + 1.2 } : c)) } }
    expect(cornersOnLines(off)).toBeNull()
    expect(cornersOnLines(typeToMetres(base()))).toEqual([
      { id: 'e1', x: 0, y: 0 },
      { id: 'e2', x: 24, y: 0 },
      { id: 'e3', x: 24, y: 16 },
      { id: 'e4', x: 0, y: 16 },
    ])
  })
})

describe('a free outline is read, edges and all', () => {
  /** A trapezoid in metres: its right wall angled. */
  const trapezoid = (): WarehouseType => ({
    ...typeToMetres(base()),
    morphology: {
      outline: [
        { id: 'e1', x: 0, y: 0 },
        { id: 'e2', x: 72, y: 0 },
        { id: 'e3', x: 60, y: 48 },
        { id: 'e4', x: 0, y: 48 },
      ],
      holes: [],
    },
  })

  it('its edges: the angled one has no axis and spans no module; the others do', () => {
    const t = trapezoid()
    const e = shapeOf(t, hallRuns(t)).edges
    expect(e.map((x) => x.axis)).toEqual(['x', null, 'x', 'y'])
    expect(e[1].outer).toBe(false)
    // the face stands out of each reference line by its wall
    const g = generate(t)
    expect(g.parts[0].polygon).toHaveLength(4)
    expect(g.walls.map((w) => w.edge)).toEqual(['e1', 'e2', 'e3', 'e4'])
  })

  it('a dock on an angled edge is left out; one on an edge along the grid stays', () => {
    const t = { ...trapezoid(), elements: [{ id: 'e1', kind: 'dock' as const, edge: 'e2', module: 3, width: 3 }, { id: 'e2', kind: 'dock' as const, edge: 'e1', module: 3, width: 3 }] }
    expect(generate(t).doors.map((d) => d.edge)).toEqual(['e1'])
  })
})
